CREATE TABLE `members` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `alias` text DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `members_name_unique` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `salary_items` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `report_date` varchar(50) DEFAULT NULL,
  `batch_id` varchar(50) DEFAULT NULL,
  `person` varchar(100) NOT NULL,
  `model` varchar(255) DEFAULT NULL,
  `storage` varchar(50) DEFAULT NULL,
  `grade` varchar(50) DEFAULT NULL,
  `obtained_price` varchar(100) DEFAULT NULL,
  `fee_info` varchar(50) DEFAULT NULL,
  `bidder` varchar(100) DEFAULT NULL,
  `status` varchar(50) DEFAULT 'approved',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_sal_report_date` (`report_date`),
  KEY `idx_sal_person` (`person`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `obtained_items` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
